PREFIX cdm: <http://publications.europa.eu/ontology/cdm#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?baseCelex ?work ?date ?inForce ?versionCelex ?versionDate WHERE {
 VALUES ?baseCelex { "32017R0565"^^xsd:string "32003L0071"^^xsd:string "32010R1095"^^xsd:string "32015R2450"^^xsd:string "32016L2341"^^xsd:string "32024L1619"^^xsd:string "32001L0034"^^xsd:string "32002L0092"^^xsd:string "32003L0006"^^xsd:string "32003L0041"^^xsd:string "32003L0124"^^xsd:string "32003L0125"^^xsd:string "32004L0072"^^xsd:string "32006R1781"^^xsd:string "32007L0036"^^xsd:string "32010R0583"^^xsd:string "32010R1094"^^xsd:string "32014L0051"^^xsd:string "32014L0059"^^xsd:string "32014R0596"^^xsd:string "32014R0680"^^xsd:string "32015R0847"^^xsd:string "32015R2452"^^xsd:string "32016L0097"^^xsd:string }
 ?work cdm:resource_legal_id_celex ?baseCelex .
 OPTIONAL { ?work cdm:work_date_document ?date . }
 OPTIONAL { ?work cdm:resource_legal_in-force ?inForce . }
 OPTIONAL { ?version cdm:act_consolidated_based_on_resource_legal ?work ; cdm:act_consolidated_date ?versionDate ; cdm:resource_legal_id_celex ?versionCelex . }
} ORDER BY ?baseCelex DESC(?versionDate) LIMIT 10000
